<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $product->localized('name') }} | {{ $shop->name }}</title>
<style>*{box-sizing:border-box}body{margin:0;background:#070a10;color:#f6f8fb;font-family:Cairo,Segoe UI,sans-serif}a{color:#61dafb}.wrap{width:min(1180px,calc(100% - 28px));margin:auto}.top{padding:18px 0}.product{display:grid;grid-template-columns:1fr 1fr;gap:28px;background:#0d141e;border:1px solid #1c3041;border-radius:28px;padding:24px}.main-img{width:100%;aspect-ratio:1/1;object-fit:contain;background:#fff;border-radius:20px}.thumbs{display:flex;gap:8px;margin-top:10px;overflow:auto}.thumbs img{width:74px;height:74px;object-fit:cover;background:#fff;border-radius:12px;cursor:pointer;border:2px solid transparent}.eyebrow{color:#61dafb}.info h1{font-size:clamp(28px,5vw,48px);margin:8px 0}.tags{display:flex;gap:7px;flex-wrap:wrap}.tag{padding:7px 10px;background:#172432;border-radius:9px;color:#c5d7e3}.price{font-size:34px;font-weight:900;margin:20px 0}.options{display:grid;gap:12px}.option{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:8px;align-items:center;padding:12px;border:1px solid #284157;border-radius:14px;cursor:pointer}.option:has(input:checked){border-color:#61dafb;background:#102331}.option.sold{opacity:.45;cursor:not-allowed}.buy{margin-top:20px;display:grid;gap:10px}.buy input,.buy textarea,.buy button{width:100%;border:1px solid #294156;background:#111c28;color:#fff;border-radius:13px;padding:13px}.buy button{background:#20b7e8;color:#00141c;font-weight:900;font-size:16px}.spec-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:26px 0}.spec{background:#0d141e;border:1px solid #1c3041;border-radius:14px;padding:14px}.spec small{display:block;color:#7991a3}.related{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:50px}.related a{background:#0d141e;padding:12px;border-radius:14px}.related img{width:100%;aspect-ratio:1;object-fit:contain;background:#fff;border-radius:10px}@media(max-width:760px){.product{grid-template-columns:1fr;padding:15px}.option{grid-template-columns:1fr 1fr}.spec-grid{grid-template-columns:1fr 1fr}.related{grid-template-columns:1fr 1fr}}</style></head>
