    $attrs = $product->catalog_attributes ?? [];
    $resolveImage = fn ($path) => $path
        ? (\Illuminate\Support\Str::startsWith($path, ['http://', 'https://', 'storage/']) ? asset($path) : asset('storage/'.$path))
