<main class="product"><section><img class="main-img" id="mainImage" src="{{ $resolveImage($product->main_image) }}"><div class="thumbs"><img src="{{ $resolveImage($product->main_image) }}">@foreach($product->images as $image)<img src="{{ $resolveImage($image->image) }}">@endforeach</div></section>
<section class="info"><div class="eyebrow">{{ data_get($attrs,'brand') }} · {{ data_get($attrs,'model') }}</div><h1>{{ $product->localized('name') }}</h1><div class="tags"><span class="tag">{{ data_get($attrs,'condition') }}</span><span class="tag">{{ data_get($attrs,'network') }}</span><span class="tag">{{ data_get($attrs,'screen_size') }}</span><span class="tag">{{ data_get($attrs,'sim_type') }}</span></div><p>{{ $product->localized('description') }}</p><div class="price" id="price">اختر التخزين واللون</div>
<div class="options">@foreach($product->variants as $variant)<label class="option {{ $variant->quantity<1?'sold':'' }}"><input type="radio" name="variant" value="{{ $variant->id }}" data-price="{{ (float)($variant->price??$product->discount_price??$product->price) }}" @disabled($variant->quantity<1)><b>{{ $variant->storage ?: 'قياسي' }}</b><span>{{ $variant->ram ? 'RAM '.$variant->ram : '' }}</span><span title="{{ $variant->color }}" style="display:inline-flex;align-items:center;gap:7px"><i style="display:inline-block;width:24px;height:24px;border-radius:50%;background:{{ $variant->color }};border:2px solid rgba(255,255,255,.7);box-shadow:0 0 0 1px rgba(0,0,0,.5)"></i>{{ $variant->color }}</span><small>{{ $variant->quantity>0 ? $variant->quantity.' متوفر' : 'نفد' }}</small></label>@endforeach</div>
<form class="buy" id="buyForm"><input name="customer_name" placeholder="الاسم الكامل" required><input name="customer_phone" placeholder="رقم الجوال" required><textarea name="customer_address" placeholder="عنوان التوصيل" required></textarea><textarea name="customer_notes" placeholder="ملاحظات اختيارية"></textarea><input type="number" name="qty" min="1" max="20" value="1"><button>تأكيد الطلب أونلاين</button><div id="message"></div></form></section></main>
<section class="spec-grid">@foreach(['processor'=>'المعالج','battery'=>'البطارية','cameras'=>'الكاميرات','battery_health'=>'صحة البطارية','warranty_months'=>'الضمان بالأشهر','included_accessories'=>'الملحقات','condition_notes'=>'حالة الجهاز'] as $key=>$label)@if(filled(data_get($attrs,$key)))<div class="spec"><small>{{ $label }}</small>{{ is_array(data_get($attrs,$key))?implode('، ',data_get($attrs,$key)):data_get($attrs,$key) }}</div>@endif @endforeach</section>
<h2>أجهزة مشابهة</h2><section class="related">@foreach($related as $item)<a href="{{ route('electronics.product',[$shop,$item]) }}"><img src="{{ $resolveImage($item->main_image) }}"><b>{{ $item->localized('name') }}</b></a>@endforeach</section></div>
<script>document.querySelectorAll('.thumbs img').forEach(img=>img.onclick=()=>mainImage.src=img.src);document.querySelectorAll('[name=variant]').forEach(v=>v.onchange=()=>price.textContent=Number(v.dataset.price).toFixed(2)+' ₪');buyForm.onsubmit=async e=>{e.preventDefault();const variant=document.querySelector('[name=variant]:checked'),message=document.getElementById('message');if(!variant){message.textContent='اختر التخزين واللون أولاً.';return}const fd=new FormData(buyForm),payload={customer_name:fd.get('customer_name'),customer_phone:fd.get('customer_phone'),customer_address:fd.get('customer_address'),customer_notes:fd.get('customer_notes'),items:[{variant_id:Number(variant.value),qty:Number(fd.get('qty'))}]};const res=await fetch(@json(route('electronics.orders.store',$shop)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify(payload)});const data=await res.json();message.textContent=res.ok?'تم تسجيل طلبك: '+data.order_number:(data.message||'تعذر تسجيل الطلب');if(res.ok)buyForm.reset()};</script></body></html>
